def trim_to_fit(words, width):
    trimmed_words = []
    current_line = ""
    for word in words:
        if len(current_line) + len(word) + 1 <= width:
            if current_line:
                current_line += " "
            current_line += word
        else:
            trimmed_words.append(current_line)
            current_line = word
    if current_line:
        trimmed_words.append(current_line)
    return [w for i, w in enumerate(words) if len(' '.join(words[:i + 1])) <= width]

