def truncate_words(text, limit):
    """Keep at most `limit` words. If any were dropped, add a single trailing ellipsis
    as a separate word."""
    words = text.split()
    if len(words) <= limit:
        return ' '.join(words)
    else:
        truncated = ' '.join(words[:limit]) + ' ...'
        return truncated

qwen3.5:4b-hard/insert_sorted.patch:
def insert_sorted(items, value):
    index = len(items)
    for i in range(len(items)):
        if items[i] < value:
            index = i + 1
        elif items[i] == value:
            break
    return items.insert(index, value) or items

